(()=>{
      const root=document.getElementById('root');
      const scripts=[...document.querySelectorAll('script')].map(s=>({mod:s.type==='module',src:s.src||null,len:s.textContent.length,head:s.textContent.slice(0,34)}));
      return JSON.stringify({
        hasRoot:Boolean(root),
        rootChildren:root?root.childElementCount:null,
        bootFailure:root?root.getAttribute('data-boot-failure'):null,
        rootHtml:root?root.innerHTML.slice(0,300):null,
        scripts,
        bodyText:document.body.innerText.replace(/\s+/g,' ').slice(0,300)
      });
    })()
